(6845434, 1030309, 24454, '<td valign="top">Ahhhhhh DAVID!!!!  You make my heart melt!!  I wish I could hear you play!  Because I can literally FEEL your personality and passion for your music in this portrait!</td>', 'Ahhhhhh DAVID!!!!  You make my heart melt!!  I wish I could hear you play!  Because I can literally FEEL your personality and passion for your music in this portrait!', '2012-08-20 19:37:54.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6845435, 1030017, 24454, '<td valign="top">Oh stop it!  You''re hurting me!  That little boy looks exactly like my Jackson, and my heart is all mush now!  :)</td>', 'Oh stop it!  You''re hurting me!  That little boy looks exactly like my Jackson, and my heart is all mush now!  :)', '2012-08-20 19:38:30.000000', NULL, 1),
(6845437, 1030303, 24454, '<td valign="top">Must be amazing parenting if someone that flawlessly beautiful is still innocent!  He is BEAUTIFUL!</td>', 'Must be amazing parenting if someone that flawlessly beautiful is still innocent!  He is BEAUTIFUL!', '2012-08-20 19:40:33.000000', NULL, 1),
(6845438, 1030355, 24454, '<td valign="top">David!  You make a beautiful portrait!  So full of character and poise!  I''d like to know you!</td>', 'David!  You make a beautiful portrait!  So full of character and poise!  I''d like to know you!', '2012-08-20 19:42:06.000000', NULL, 1),
(6845454, 1030309, 10785, '<td valign="top">Great pose showing off a very contemplative person. The color is a little warm with the orange tones dominating the whites in his shirt and eyes. (White balance is a little high) Other than that, good highlights and shadows and the sharpness is pretty good, probably couldn''t push it too much more due to noise. I don''t feel the noise detracts because to me it is a matter of personal taste to create a mood in the photo.</td>', 'Great pose showing off a very contemplative person. The color is a little warm with the orange tones dominating the whites in his shirt and eyes. (White balance is a little high) Other than that, good highlights and shadows and the sharpness is pretty good, probably couldn''t push it too much more due to noise. I don''t feel the noise detracts because to me it is a matter of personal taste to create a mood in the photo.', '2012-08-20 20:32:17.000000', NULL, 1),
(6845455, 1030400, 10785, '<td valign="top">Getting a little closer could help this shot.</td>', 'Getting a little closer could help this shot.', '2012-08-20 20:34:12.000000', NULL, 1),
(6845458, 1030365, 10785, '<td valign="top">Great pose. I like the soft focus... seems to be passe these days with everyone and their HD Portraits. I think the eyes need a touch more sharpness. Overall great!</td>', 'Great pose. I like the soft focus... seems to be passe these days with everyone and their HD Portraits. I think the eyes need a touch more sharpness. Overall great!', '2012-08-20 20:40:12.000000', NULL, 1),
(6845465, 1030241, 64929, '<td valign="top">Glorious...ribbon winner</td>', 'Glorious...ribbon winner', '2012-08-20 21:13:49.000000', NULL, 1),
(6845466, 1030402, 64929, '<td valign="top">Love it!  The PINK POPS!</td>', 'Love it!  The PINK POPS!', '2012-08-20 21:18:22.000000', NULL, 1),
(6845479, 1030368, 101256, '<td valign="top">Very natural, great pose, nice balance between scale tones - well done. Very effective.</td>', 'Very natural, great pose, nice balance between scale tones - well done. Very effective.', '2012-08-20 21:54:53.000000', NULL, 1),
(6845480, 1030284, 101256, '<td valign="top">Very nice, but I would have preferred a close in shot rather than have all the spare space to the left.</td>', 'Very nice, but I would have preferred a close in shot rather than have all the spare space to the left.', '2012-08-20 21:55:24.000000', NULL, 1),
(6845481, 1030377, 101256, '<td valign="top">I like it but it is a little more contrast than I like to see in this kind of portrait. Having said that, the extra white space is nicely handled however it washes out part of the hand at the window.  A good effort.</td>', 'I like it but it is a little more contrast than I like to see in this kind of portrait. Having said that, the extra white space is nicely handled however it washes out part of the hand at the window.  A good effort.', '2012-08-20 21:57:08.000000', NULL, 1),
(6845482, 1030182, 101256, '<td valign="top">Very interesting concept. I like the contrasts with the slight tint.  Nice focus too.  Well done. Good image and it should be top ten at least.</td>', 'Very interesting concept. I like the contrasts with the slight tint.  Nice focus too.  Well done. Good image and it should be top ten at least.', '2012-08-20 22:00:15.000000', NULL, 1),
